Q: XML format from SQL data table A: <p>Please try the following solution.</p>
<p>You just need to add one more level to the XML hierarchy.</p>
<p>XML is case-sensitive. Your T-SQL element names are not matching the desired output.</p>
<p>For example: <code>PATH('user') &lt;&gt; PATH('USER')</code></p>
<p>It is better to use <code>FOR XML PATH()</code> clause for XML composition.</p>
<p><strong>SQL</strong></p>
<pre><code>
-- DDL and sample data population, start
CREATE TABLE students (
    id   INT PRIMARY KEY,
    name VARCHAR(100) NOT NULL
);

CREATE TABLE classes (
    class_id   INT IDENTITY PRIMARY KEY,
    student_id INT NOT NULL,
    class_name VARCHAR(100) NOT NULL,
    FOREIGN KEY (student_id) REFERENCES students(id)
);

INSERT INTO students (id, name)
VALUES (123, 'abc'),
       (200, 'john');   -- extra student to show multi-row behavior

INSERT INTO classes (student_id, class_name)
VALUES (123, 'xyx'),
       (123, 'math'),
       (200, 'history');
-- DDL and sample data population, end

SELECT
    u.id,
    u.name,
    (
        SELECT
            (
                SELECT
                    c.class_name
                FROM classes AS c
                WHERE c.student_id = u.id
                FOR XML PATH('student_class'), TYPE
            )
        FOR XML PATH('student_classes'), TYPE
    ) AS student
FROM students AS u
FOR XML PATH('user'), TYPE, ROOT('users');

</code></pre>
<p><strong>Output</strong></p>
<pre><code>&lt;users&gt;
  &lt;user&gt;
    &lt;id&gt;123&lt;/id&gt;
    &lt;name&gt;abc&lt;/name&gt;
    &lt;student&gt;
      &lt;student_classes&gt;
        &lt;student_class&gt;
          &lt;class_name&gt;xyx&lt;/class_name&gt;
        &lt;/student_class&gt;
        &lt;student_class&gt;
          &lt;class_name&gt;math&lt;/class_name&gt;
        &lt;/student_class&gt;
      &lt;/student_classes&gt;
    &lt;/student&gt;
  &lt;/user&gt;
  &lt;user&gt;
    &lt;id&gt;200&lt;/id&gt;
    &lt;name&gt;john&lt;/name&gt;
    &lt;student&gt;
      &lt;student_classes&gt;
        &lt;student_class&gt;
          &lt;class_name&gt;history&lt;/class_name&gt;
        &lt;/student_class&gt;
      &lt;/student_classes&gt;
    &lt;/student&gt;
  &lt;/user&gt;
&lt;/users&gt;
</code></pre>
